#pragma once
// Minimal config.h for Emscripten/WASM build.
// Generated by configure on a standard Linux build; we replicate only what the
// WASM target actually needs.

#define PACKAGE_VERSION "1.51"

// mkstemp is available via Emscripten's POSIX layer.
#define HAVE_MKSTEMP 1

// sleep() is available.
#define HAVE_SLEEP 1

// No pcaudiolib (we never play audio from WASM).
// #undef HAVE_PCAUDIOLIB_AUDIO_H

// No async speech queue — avoids pthreads dependency.
// #undef USE_ASYNC

// No assembler optimisations.
// #undef USE_ASSEMBLER_1
